// Validate that the server responds successfully
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Extract the token and save it to the Environment
const response = pm.response.json();

if (response.token) {
    pm.environment.set("token", response.token);
    console.log("Token captured and saved: " + response.token);
} else {
    pm.test("Token is present in the response", function () {
        throw new Error("The 'token' field is not present in the response. Please verify the credentials.");
    });
}

// --- 1. STATUS CODE VALIDATION ---
pm.test("Status code is 200 - OK", function () {
    pm.response.to.have.status(200);
});

// --- 2. RESPONSE TIME VALIDATION (SLA) ---
// Verify that the API responds quickly.
// The test will fail if the response time exceeds 800ms.
pm.test("Response time is less than 800ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(800);
});

// --- 3. JSON SCHEMA VALIDATION (Contract Testing) ---
// Define the expected response structure.
const bookingSchema = {
    "type": "object",
    "required": ["bookingid", "booking"],
    "properties": {
        "bookingid": { "type": "number" },
        "booking": {
            "type": "object",
            "required": ["firstname", "lastname", "totalprice", "depositpaid", "bookingdates"],
            "properties": {
                "firstname": { "type": "string" },
                "lastname": { "type": "string" },
                "totalprice": { "type": "number" },
                "depositpaid": { "type": "boolean" },
                "bookingdates": {
                    "type": "object",
                    "required": ["checkin", "checkout"],
                    "properties": {
                        "checkin": { "type": "string" },
                        "checkout": { "type": "string" }
                    }
                },
                "additionalneeds": { "type": "string" }
            }
        }
    }
};

// Validate the response contract using Postman's built-in schema validator
pm.test("Response JSON schema is valid", function () {
    pm.response.to.have.jsonSchema(bookingSchema);
});

// --- 4. DATA EXTRACTION ---
// Save the booking ID for use in subsequent requests.
const response = pm.response.json();

if (response.bookingid) {
    pm.environment.set("booking_id", response.bookingid);
    console.log("Booking ID saved successfully: " + response.bookingid);
}

// 1. STATUS CODE VALIDATION
pm.test("Status code is 200 - Booking Updated", function () {
    pm.response.to.have.status(200);
});

// 2. DATA VALIDATION
const response = pm.response.json();

pm.test("Updated booking contains the expected first name", function () {
    pm.expect(response.firstname).to.eql("James");
});

pm.test("Updated booking contains the expected total price", function () {
    pm.expect(response.totalprice).to.eql(150);
});

// The API returns 201 Created when a booking is successfully deleted
pm.test("Status code is 201 - Booking Deleted", function () {
    pm.response.to.have.status(201);
});

// RESPONSE TIME VALIDATION
pm.test("Response time is less than 800ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(800);
});
